//! LM-410 — `product_inputs::for_security` and `valuation_requests::typed`.
//!
//! The shared cases live in test-fixtures/product-inputs/, one file per case,
//! generated by ledger-models-python/test/requests/test_product_input_builders.py
//! and read by the Java, Python and JS tests too. The directory is listed at
//! run time, so a new case is picked up without editing this file.
//! See docs/adr/product_input_builders.md.

use std::collections::BTreeSet;
use std::path::PathBuf;

use ledger_models::fintekkers::models::position::{MeasureProto, PositionProto};
use ledger_models::fintekkers::models::price::PriceProto;
use ledger_models::fintekkers::models::security::SecurityProto;
use ledger_models::fintekkers::models::util::LocalTimestampProto;
use ledger_models::fintekkers::requests::valuation::product_input::Input;
use ledger_models::fintekkers::requests::valuation::{
    BondInput, InflationIndexInput, ProductInput, ReferenceRateFixingProto, YieldCurveInput,
};
use ledger_models::fintekkers::wrappers::models::product_inputs::{
    arm_for, check_product_input, for_security, MarketData, MarketDataKind, ProductInputError,
};
use ledger_models::fintekkers::wrappers::models::valuation_requests::typed;
use prost::Message;
use serde_json::Value;

struct Case {
    name: String,
    json: Value,
}

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../test-fixtures/product-inputs")
}

fn cases() -> Vec<Case> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(fixtures_dir())
        .expect("list fixtures")
        .map(|e| e.expect("fixture entry").path())
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .collect();
    paths.sort();
    paths
        .into_iter()
        .map(|p| Case {
            name: p.file_stem().unwrap().to_string_lossy().to_string(),
            json: serde_json::from_str(&std::fs::read_to_string(&p).expect("read fixture")).expect("parse fixture"),
        })
        .collect()
}

fn success_cases() -> Vec<Case> {
    cases().into_iter().filter(|c| c.json.get("arm").is_some()).collect()
}

fn error_cases() -> Vec<Case> {
    cases().into_iter().filter(|c| c.json.get("error").is_some()).collect()
}

fn fixture(name: &str) -> Case {
    cases().into_iter().find(|c| c.name == name).expect("fixture")
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex")).collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn parse<M: Message + Default>(v: &Value) -> M {
    M::decode(unhex(v.as_str().expect("hex string")).as_slice()).expect("decode")
}

fn security(c: &Case) -> SecurityProto {
    parse(&c.json["security_hex"])
}

fn price(c: &Case) -> PriceProto {
    parse(&c.json["price_hex"])
}

fn market_data(c: &Case) -> MarketData {
    let md = &c.json["market_data"];
    MarketData {
        cpi: md.get("cpi_hex").map(parse::<InflationIndexInput>),
        fixings: md
            .get("fixings_hex")
            .and_then(Value::as_array)
            .map(|a| a.iter().map(parse::<ReferenceRateFixingProto>).collect())
            .unwrap_or_default(),
        curve: md.get("curve_hex").map(parse::<YieldCurveInput>),
    }
}

fn typed_args(c: &Case) -> (LocalTimestampProto, PositionProto, Vec<MeasureProto>) {
    let t = &c.json["typed"];
    let measures = t["measures"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| MeasureProto::from_str_name(m.as_str().unwrap()).expect("measure name"))
        .collect();
    (parse(&t["asof_hex"]), parse(&t["position_hex"]), measures)
}

fn assert_error(name: &str, err: &ProductInputError, expected: &Value) {
    match (expected["type"].as_str().unwrap(), err) {
        ("MissingMarketDataError", ProductInputError::MissingMarketData(e)) => {
            assert_eq!(e.arm, expected["arm"].as_str().unwrap(), "{name}");
            assert_eq!(e.kind.as_str_name(), expected["kind"].as_str().unwrap(), "{name}");
            assert_eq!(e.field, expected["field"].as_str().unwrap(), "{name}");
            let message = err.to_string();
            assert!(message.contains(&e.arm) && message.contains(e.kind.as_str_name()), "{name}: {message}");
            assert_eq!(err.violations()[0].field, e.field, "{name}");
        }
        ("UnmappedProductTypeError", ProductInputError::Unmapped { .. }) => {}
        (want, got) => panic!("{name}: want {want}, got {got:?}"),
    }
}

// ---------- for_security ----------

#[test]
fn fixtures_cover_every_arm_in_valuation_arms() {
    // The crate-root mirror that sync-hierarchy-mirrors.sh writes and the library embeds.
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("hierarchy.json");
    let root: Value = serde_json::from_str(&std::fs::read_to_string(path).expect("read mirror")).unwrap();
    let arms: BTreeSet<String> = root["valuation_arms"]["entries"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["arm"].as_str().unwrap().to_string())
        .collect();
    let fixture_arms: Vec<String> = success_cases().iter().map(|c| c.json["arm"].as_str().unwrap().to_string()).collect();
    assert_eq!(arms, fixture_arms.iter().cloned().collect::<BTreeSet<_>>());
    assert_eq!(arms.len(), fixture_arms.len(), "one success fixture per arm");
}

#[test]
fn for_security_matches_fixture_bytes() {
    for c in success_cases() {
        let out = for_security(&security(&c), &price(&c), &market_data(&c)).expect(&c.name);
        assert_eq!(hex(&out.encode_to_vec()), c.json["expected_hex"].as_str().unwrap(), "{}", c.name);
    }
}

/// R1: the arm is `arm_for`'s, and each field is the input it came from.
#[test]
fn for_security_fields() {
    for c in success_cases() {
        let (s, p, md) = (security(&c), price(&c), market_data(&c));
        let out = for_security(&s, &p, &md).expect(&c.name);
        let expected_arm = c.json["arm"].as_str().unwrap();
        assert_eq!(arm_for(&s).unwrap(), expected_arm, "{}", c.name);
        let sec = Some(s.clone());
        match out.input.expect("arm set") {
            Input::Bond(b) => {
                assert_eq!(expected_arm, "bond");
                assert_eq!((b.security, b.clean_price, b.cost_basis), (sec, p.price.clone(), None));
            }
            Input::Tips(t) => {
                assert_eq!(expected_arm, "tips");
                assert_eq!((t.security, t.clean_price, t.cost_basis), (sec, p.price.clone(), None));
                assert_eq!(t.cpi, md.cpi);
            }
            Input::Frn(f) => {
                assert_eq!(expected_arm, "frn");
                assert_eq!((f.security, f.clean_price, f.cost_basis), (sec, p.price.clone(), None));
                assert_eq!((f.curve, f.fixings), (md.curve.clone(), md.fixings.clone()));
            }
            Input::Mbs(m) => {
                assert_eq!(expected_arm, "mbs");
                assert_eq!((m.security, m.clean_price, m.cost_basis), (sec, p.price.clone(), None));
            }
            // EquityInput and CashInput have unit_price and no clean_price field.
            Input::Equity(e) => {
                assert_eq!(expected_arm, "equity");
                assert_eq!((e.security, e.unit_price), (sec, p.price.clone()));
            }
            Input::Cash(k) => {
                assert_eq!(expected_arm, "cash");
                assert_eq!((k.security, k.unit_price), (sec, p.price.clone()));
            }
        }
    }
}

#[test]
fn for_security_returns_fixture_error() {
    let cases = error_cases();
    assert!(!cases.is_empty());
    for c in cases {
        let err = for_security(&security(&c), &price(&c), &market_data(&c)).expect_err(&c.name);
        assert_error(&c.name, &err, &c.json["error"]);
    }
}

#[test]
fn for_security_with_default_market_data_is_missing_cpi() {
    let c = fixture("tips");
    match for_security(&security(&c), &price(&c), &MarketData::default()) {
        Err(ProductInputError::MissingMarketData(e)) => assert_eq!((e.arm.as_str(), e.kind), ("tips", MarketDataKind::CpiU)),
        other => panic!("want MissingMarketData, got {other:?}"),
    }
}

// ---------- valuation_requests::typed ----------

#[test]
fn typed_matches_fixture_and_sets_only_typed_fields() {
    for c in success_cases() {
        let product_input = for_security(&security(&c), &price(&c), &market_data(&c)).expect(&c.name);
        let (asof, position, measures) = typed_args(&c);
        let request = typed(asof, product_input.clone(), position.clone(), &measures).expect(&c.name);
        assert_eq!(hex(&request.encode_to_vec()), c.json["typed"]["expected_hex"].as_str().unwrap(), "{}", c.name);
        assert_eq!(request.position_input, Some(position), "{}", c.name);
        assert_eq!(request.product_input, Some(product_input), "{}", c.name);
    }
}

#[test]
fn typed_returns_fixture_error() {
    for c in error_cases() {
        let product_input: ProductInput = parse(&c.json["typed"]["product_input_hex"]);
        let (asof, position, measures) = typed_args(&c);
        let err = typed(asof, product_input, position, &measures).expect_err(&c.name);
        assert_error(&c.name, &err, &c.json["error"]);
    }
}

#[test]
fn typed_rejects_an_arm_arm_for_did_not_pick() {
    let c = fixture("tips");
    let wrong = ProductInput {
        input: Some(Input::Bond(BondInput {
            security: Some(security(&c)),
            clean_price: price(&c).price,
            ..Default::default()
        })),
    };
    let (asof, position, measures) = typed_args(&c);
    match typed(asof, wrong, position, &measures) {
        Err(ProductInputError::Validation(v)) => assert_eq!(v[0].field, "product_input.bond"),
        other => panic!("want Validation, got {other:?}"),
    }
}

#[test]
fn typed_rejects_an_input_with_no_arm() {
    let (asof, position, measures) = typed_args(&fixture("bond"));
    match typed(asof, ProductInput::default(), position, &measures) {
        Err(ProductInputError::Validation(v)) => assert_eq!(v[0].field, "product_input"),
        other => panic!("want Validation, got {other:?}"),
    }
    assert!(check_product_input(&ProductInput::default()).is_err());
}

#[test]
fn errors_map_to_invalid_argument() {
    let c = fixture("tips-missing-cpi");
    let err = for_security(&security(&c), &price(&c), &market_data(&c)).expect_err("missing cpi");
    assert_eq!(tonic::Status::from(err).code(), tonic::Code::InvalidArgument);
}
